WITH valid AS (SELECT *, DATE_SUB(last_restock, 3) AS last_restock_minus_3d, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE quantity BETWEEN 210 AND 212) SELECT d.city, d.region, COUNT(*) AS num_rows, ROUND(SUM(s.days_since_last_restock), 2) AS total_days_since_last_restock FROM valid s INNER JOIN stores d ON s.store_id = d.id GROUP BY GROUPING SETS ((d.city, d.region), (d.city));
